import{_ as r,a0 as n,w as p,s,ao as m,I as o,a1 as a,A as i,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse(`{"title":"15 個‘ls’命令的面試問題（一） | LCTT x X-CMD","titleTemplate":false,"description":"15 個‘ls’命令的面試問題（一） | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"15 個‘ls’命令的面試問題（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"15 個‘ls’命令的面試問題（一） | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150309 15 Interview Questions on Linux 'ls ' Command--Part 1","title":"15 個‘ls’命令的面試問題（一）","tag":"201504","desc":""},"relativePath":"201504/20150309 15 Interview Questions on Linux 'ls ' Command--Part 1.md","filePath":"[post].md"}`),c={name:"201504/20150309 15 Interview Questions on Linux 'ls ' Command--Part 1.md"};function d(h,e,u,w,f,x){const l=n("Link");return p(),s("div",null,[e[15]||(e[15]=m(`<h1 id="_15-個-ls-命令的面試問題-一" tabindex="-1">15 個‘ls’命令的面試問題（一） <a class="header-anchor" href="#_15-個-ls-命令的面試問題-一" aria-label="Permalink to “15 個‘ls’命令的面試問題（一）”">​</a></h1><p>Unix或類Unix系統中的“文件列表”命令“ls”是最基礎並且使用的最廣泛的命令列中工具之一。它是一個POSIX兼容工具，在GNU基本工具集以及BSD各種變體上都可以使用。“ls”命令可以結合大量的選項來達到想要的結果。</p><p>這篇文章的目的在於通過相關的樣例來深入討論文件列表命令。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/ls-Command-Questions.png" alt="15 ls Command Questions"></p><p><em>15個“ls”命令問題。</em></p><h3 id="_1-如何列出目錄中的文件" tabindex="-1">1. 如何列出目錄中的文件？### <a class="header-anchor" href="#_1-如何列出目錄中的文件" aria-label="Permalink to “1. 如何列出目錄中的文件？###”">​</a></h3><p>答：linux文件列表命令“ls”就是幹這個的。</p><pre><code># ls
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-files.gif" alt="List Files"></p><p><em>列出文件</em></p><p>同時，我們也可以使用“echo(回顯)”命令與一個通配符(*)參數來雷錘目錄中的所有文件。</p><pre><code># echo *
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-all-files.gif" alt="List All Files"></p><p><em>列出所有的文件。</em></p><h3 id="_2-如何只使用echo命令來只列出所有目錄" tabindex="-1">2. 如何只使用echo命令來只列出所有目錄？### <a class="header-anchor" href="#_2-如何只使用echo命令來只列出所有目錄" aria-label="Permalink to “2. 如何只使用echo命令來只列出所有目錄？###”">​</a></h3><pre><code># echo */
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-all-directories.gif" alt="List All Directories"></p><p><em>列出所有的目錄</em></p><h3 id="_3-怎樣列出一個目錄中的所有文件-包括隱藏的以-開頭的文件" tabindex="-1">3. 怎樣列出一個目錄中的所有文件， 包括隱藏的以“.”開頭的文件？### <a class="header-anchor" href="#_3-怎樣列出一個目錄中的所有文件-包括隱藏的以-開頭的文件" aria-label="Permalink to “3.  怎樣列出一個目錄中的所有文件， 包括隱藏的以“.”開頭的文件？###”">​</a></h3><p>答：我們需要將“-a”選項與“ls”命令一起使用。</p><pre><code># ls -a
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-all-hidden-files.gif" alt="List All Hidden Files"></p><p><em>列出所有的隱藏文件。</em></p><h3 id="_4-如何列出目錄中除了-當前目錄-和-父目錄-之外的所有文件-包括隱藏文件" tabindex="-1">4. 如何列出目錄中除了 “當前目錄 .”和“父目錄 ..”之外的所有文件，包括隱藏文件？### <a class="header-anchor" href="#_4-如何列出目錄中除了-當前目錄-和-父目錄-之外的所有文件-包括隱藏文件" aria-label="Permalink to “4. 如何列出目錄中除了 “當前目錄 .”和“父目錄 ..”之外的所有文件，包括隱藏文件？###”">​</a></h3><p>答： 我們需要將“-A”選項與“ls”命令一起使用</p><pre><code># ls -A
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Do-not-list-Implied.gif" alt="Do Not List Implied"></p><p><em>別列出指代當前目錄和父目錄的文件</em></p><h3 id="_5-如何使用長格式打印出當前目錄內容" tabindex="-1">5. 如何使用長格式打印出當前目錄內容？### <a class="header-anchor" href="#_5-如何使用長格式打印出當前目錄內容" aria-label="Permalink to “5. 如何使用長格式打印出當前目錄內容？###”">​</a></h3><p>答： 我們需要將“-l”選項與“ls”命令一起使用。</p><pre><code># ls -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/list-files-long.gif" alt="List Files Long"></p><p><em>列出文件的長格式。</em></p><p>上面的樣例中，其輸出結果看起來向下面這樣。</p><pre><code>drwxr-xr-x  5 avi tecmint      4096 Sep 30 11:31 Binary
</code></pre><p>上面的drwxr-xr-x 是文件的權限，分別代表了文件所有者，所屬組以及“整個世界”。 所有者具有讀(r),寫(w)以及執行(x)等權限。 該文件所屬組具有讀(r)和執行(x)但是沒有寫的權限，整個世界的其他可以訪問到該文件的人也具有相同權限。</p><ul><li>開頭的‘d’意味着這是一個目錄</li><li>數字&#39;5&#39;表示符號鏈接（有5個符號鏈接）</li><li>文件 Binary歸屬於用户 “avi”以及用户組 &quot;tecmint&quot;</li><li>Sep 30 11:31 表示文件最後一次的訪問日期與時間。</li></ul><h3 id="_6-假如讓你來將目錄中的內容以長格式列表打印-並且顯示出隱藏的-點文件-你會如何實現" tabindex="-1">6. 假如讓你來將目錄中的內容以長格式列表打印，並且顯示出隱藏的“點文件”，你會如何實現？### <a class="header-anchor" href="#_6-假如讓你來將目錄中的內容以長格式列表打印-並且顯示出隱藏的-點文件-你會如何實現" aria-label="Permalink to “6. 假如讓你來將目錄中的內容以長格式列表打印，並且顯示出隱藏的“點文件”，你會如何實現？###”">​</a></h3><p>答： 我們需要同時將&quot;-a&quot;和&quot;-l&quot;選項與“ls”命令一起使用（LCTT 譯註：單字符選項可以合併寫）。</p><pre><code># ls -la
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Print-Content-of-Directory.gif" alt="Print Content of Directory"></p><p><em>打印目錄內容</em></p><p>此外，如果我們不想列出“當前目錄”和&quot;父目錄&quot;，可以將“-A”和“-l”選項同“ls”命令一起使用。</p><pre><code># ls -lA
</code></pre><h3 id="_7-如何找到每個文件的創建者" tabindex="-1">7. 如何找到每個文件的創建者？### <a class="header-anchor" href="#_7-如何找到每個文件的創建者" aria-label="Permalink to “7. 如何找到每個文件的創建者？###”">​</a></h3><p>答： 我們需要結合 “--author”和 &quot;-l&quot;選項來打印出每個文件的創建者。</p><pre><code># ls --author -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-Author-Files.gif" alt="List Author Files"></p><p><em>列出文件創建者。</em></p><h3 id="_8-如何對用轉義字符打印出非顯示字符" tabindex="-1">8. 如何對用轉義字符打印出非顯示字符？### <a class="header-anchor" href="#_8-如何對用轉義字符打印出非顯示字符" aria-label="Permalink to “8. 如何對用轉義字符打印出非顯示字符？###”">​</a></h3><p>答：我們只需要使用“-b”選項來對非顯示字符進行轉義打印</p><pre><code># ls -b
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Print-Escape-Character.gif" alt="Print Escape Character"></p><h3 id="_9-用指定特定的單位格式來列出文件和目錄的大小-你會如何實現" tabindex="-1">9. 用指定特定的單位格式來列出文件和目錄的大小，你會如何實現？### <a class="header-anchor" href="#_9-用指定特定的單位格式來列出文件和目錄的大小-你會如何實現" aria-label="Permalink to “9. 用指定特定的單位格式來列出文件和目錄的大小，你會如何實現？###”">​</a></h3><p>答： 在此可以同時使用選項“-block-size=scale”和“-l”，但是我們需要用特定的單位如M，K等來替換‘scale’參數。</p><pre><code># ls --block-size=M -l
# ls --block-size=K -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-File-Scale-Format.gif" alt="List File Scale Format"></p><p><em>列出文件大小單位格式。</em></p><h3 id="_10-列出目錄中的文件-但是不顯示備份文件-即那些文件名以-結尾的文件" tabindex="-1">10. 列出目錄中的文件，但是不顯示備份文件，即那些文件名以‘~’結尾的文件### <a class="header-anchor" href="#_10-列出目錄中的文件-但是不顯示備份文件-即那些文件名以-結尾的文件" aria-label="Permalink to “10. 列出目錄中的文件，但是不顯示備份文件，即那些文件名以‘~’結尾的文件###”">​</a></h3><p>答： 選項‘-B’趕來救駕。</p><pre><code># ls -B
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-File-Without-Backup.gif" alt="List File Without Backup"></p><p><em>列出非備份文件</em></p><h3 id="_11-將目錄中的所有文件按照名稱進行排序-並顯示其最後修改時間信息" tabindex="-1">11. 將目錄中的所有文件按照名稱進行排序，並顯示其最後修改時間信息？### <a class="header-anchor" href="#_11-將目錄中的所有文件按照名稱進行排序-並顯示其最後修改時間信息" aria-label="Permalink to “11. 將目錄中的所有文件按照名稱進行排序，並顯示其最後修改時間信息？###”">​</a></h3><p>答： 為了實現這個需求，我們需要同時將“-c”和&quot;-l&quot;選項與命令一起使用。</p><pre><code># ls -cl
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Sort-Files.gif" alt="Sort Files"></p><p><em>文件排序</em></p><h3 id="_12-將目錄中的文件按照修改時間進行排序-並顯示相關聯的信息。" tabindex="-1">12. 將目錄中的文件按照修改時間進行排序，並顯示相關聯的信息。### <a class="header-anchor" href="#_12-將目錄中的文件按照修改時間進行排序-並顯示相關聯的信息。" aria-label="Permalink to “12. 將目錄中的文件按照修改時間進行排序，並顯示相關聯的信息。###”">​</a></h3><p>答： 我們需要同時使用3個選項：&#39;-l&#39;,&#39;-t&#39;,&#39;-c&#39; 來對文件使用修改時間排序，最新的修改時間排在最前。</p><pre><code># ls -ltc
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Sort-Files-by-Modification.gif" alt="Sort Files by Modification"></p><p><em>按照修改時間對文件排序。</em></p><h3 id="_13-如何控制-ls-命令的輸出顏色的有無" tabindex="-1">13. 如何控制‘ls’命令的輸出顏色的有無？### <a class="header-anchor" href="#_13-如何控制-ls-命令的輸出顏色的有無" aria-label="Permalink to “13. 如何控制‘ls’命令的輸出顏色的有無？###”">​</a></h3><p>答： 需要使用選項‘--color=parameter’，參數具有三種不同值，“auto(自動)”，“always(一直)”，“never(無色)”。</p><pre><code># ls --color=never
# ls --color=auto
# ls --color=always
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/ls-colorful-output.gif" alt="ls Colorful Output"></p><p><em>ls的輸出顏色</em></p><h3 id="_14-假如只需要列出目錄本身-而不是目錄的內容-你會如何做" tabindex="-1">14. 假如只需要列出目錄本身，而不是目錄的內容，你會如何做？### <a class="header-anchor" href="#_14-假如只需要列出目錄本身-而不是目錄的內容-你會如何做" aria-label="Permalink to “14. 假如只需要列出目錄本身，而不是目錄的內容，你會如何做？###”">​</a></h3><p>答：在此“-d”選項就會顯得很順手。</p><pre><code># ls -d
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-Directory-Entries.gif" alt="List Directory Entries"></p><p><em>列出目錄本身</em></p><h3 id="_15-為長格式列表命令-ls-l-創建一個別名-ll-並將其結果輸出到一個文件而不是標準輸出中。" tabindex="-1">15. 為長格式列表命令&quot;ls -l&quot;創建一個別名“ll”，並將其結果輸出到一個文件而不是標準輸出中。### <a class="header-anchor" href="#_15-為長格式列表命令-ls-l-創建一個別名-ll-並將其結果輸出到一個文件而不是標準輸出中。" aria-label="Permalink to “15. 為長格式列表命令ls -l創建一個別名“ll”，並將其結果輸出到一個文件而不是標準輸出中。###”">​</a></h3><p>答：在上述的這個場景中，我們需要將別名添加到.bashrc文件中，然後使用重定向操作符將輸出寫入到文件而不是標準輸出中。我們將會使用編輯器nano。</p><pre><code># ls -a
# nano .bashrc
# ll &gt;&gt; ll.txt
# nano ll.txt
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Create-ls-Alias.gif" alt="Create Alias for ls command"></p><p><em>為ls命令創建別名。</em></p><p>先到此為止，別忘了在下面的評論中提出你們的寶貴意見，我會再次帶着另外的有趣的文章在此閃亮登場。</p><h3 id="參考閲讀" tabindex="-1">參考閲讀：### <a class="header-anchor" href="#參考閲讀" aria-label="Permalink to “參考閲讀：###”">​</a></h3>`,90)),o("ul",null,[o("li",null,[a(l,{href:"http://www.tecmint.com/ls-interview-questions/"},{default:i(()=>[...e[0]||(e[0]=[t("10 個‘ls’命令的面試問題（二）",-1)])]),_:1})]),o("li",null,[a(l,{href:"http://linux.cn/article-5109-1.html"},{default:i(()=>[...e[1]||(e[1]=[t("Linux中15個基礎的'ls'命令",-1)])]),_:1})])]),e[16]||(e[16]=o("hr",null,null,-1)),o("p",null,[e[3]||(e[3]=t("via: ",-1)),a(l,{href:"http://www.tecmint.com/ls-command-interview-questions/"},{default:i(()=>[...e[2]||(e[2]=[t("http://www.tecmint.com/ls-command-interview-questions/",-1)])]),_:1})]),o("p",null,[e[7]||(e[7]=t("作者：",-1)),a(l,{href:"http://www.tecmint.com/author/avishek/"},{default:i(()=>[...e[4]||(e[4]=[t("Avishek Kumar",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),a(l,{href:"https://github.com/theo-l"},{default:i(()=>[...e[5]||(e[5]=[t("theo-l",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),a(l,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:i(()=>[...e[6]||(e[6]=[t("校對者ID",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創翻譯，",-1)),a(l,{href:"http://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const L=r(c,[["render",d]]);export{_ as __pageData,L as default};
